function createMailTransporter(config2) {
  const host = config2.host;
  const user = config2.user;
  const pass = config2.pass;
  const port = parseInt(String(config2.port || "587"), 10);
  if (!host || !user || !pass) {
    return null;
  }
  return import_nodemailer.default.createTransport({
    host,
    port,
    secure: port === 465,
    auth: { user, pass }
  });
}
